// Canonical artifact names, as returned by list_code_project_artifacts.
// minItems: 1, maxItems: 20
artifactNames: Array<
string // minLength: 1, maxLength: 1024
>,
// Maximum table rows or top-level list items/object keys per artifact, defaulting to 20 and up to 100.
limit?: integer, // minimum: 1, maximum: 100
// Parameter overrides keyed by their names in hexdag.yaml, for this evaluation only. Omitted parameters use project defaults; saved configuration is unchanged.
parameters?: { [key: string]: any },
// The code project's project ref. Every file and DAG operation is scoped to a project ref. Use the projectRefId returned by create_code_project, or the segment after /refs/ in the code-project editor URL.
projectRefId: string,
// Refresh the selected artifacts before evaluating them. Cached upstream inputs may still be reused; list upstream source artifacts too when they need fresh data. Defaults to false.
rerun?: boolean,
// ID of the external agent run this call belongs to. Create one with `create_agent_run` and pass its runId on tools that declare it.
runId: string, // format: "uuid"
}): Promise<{
